// Generated by vibelang from src/features/docs/text.ts; the migrate flow writes it again with each batch.
// Bounding a docs page's Markdown (docs/features/docs.md#the-docs-view): a `docs` view keeps at most 64 KiB of it, and
// the agent hears at most 12 KiB of each page it showed. Pure, so ChatApi, the flow's steps and the tests share it.
const encoder = new TextEncoder();
const decoder = new TextDecoder();
/**
 * `text` in at most `maxBytes` bytes of UTF-8, cut before the first character that doesn't fit, and whether it was
 * cut. A character is never split.
 */
export const cutText = (text, maxBytes) => {
    const bytes = encoder.encode(text);
    if (bytes.length <= maxBytes)
        return { text, truncated: false };
    let end = maxBytes;
    // Back up to the first byte of the character the cut would split: a continuation byte is 0b10xxxxxx.
    while (end > 0 && (bytes[end] & 0xc0) === 0x80)
        end -= 1;
    return { text: decoder.decode(bytes.subarray(0, end)), truncated: true };
};
